// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        bytes32 admin = c.getRoleAdmin(role);
        if (role == 0x00) {
            assertTrue(admin == 0x00);
        } else if (role == keccak256("TIMELOCK_ADMIN_ROLE")) {
            assertTrue(admin == keccak256("TIMELOCK_ADMIN_ROLE"));
        } else if (role == keccak256("PROPOSER_ROLE")) {
            assertTrue(admin == keccak256("TIMELOCK_ADMIN_ROLE"));
        } else if (role == keccak256("EXECUTOR_ROLE")) {
            assertTrue(admin == keccak256("TIMELOCK_ADMIN_ROLE"));
        } else {
            assertTrue(admin == 0x00);
        }
    }
}
